const chapters = [...document.querySelectorAll('.chapter')];
const next = document.querySelector('#next');
const previous = document.querySelector('#previous');
const page = document.querySelector('#page');
const labels = ['How did it spread?', 'Was there already a fix?', 'Then came an unexpected twist…', 'What’s the takeaway?', 'Read it again'];
let current = 0;
function show(index) {
  current = (index + chapters.length) % chapters.length;
  chapters.forEach((chapter, i) => { chapter.hidden = i !== current; });
  document.querySelectorAll('[data-progress]').forEach((marker, i) => marker.classList.toggle('current', i === current));
  previous.disabled = current === 0;
  next.textContent = labels[current] + ' →';
  page.textContent = (current + 1) + ' / ' + chapters.length;
  window.scrollTo({top:0,behavior:'instant'});
  chapters[current].querySelector('h1').focus({preventScroll:true});
}
next.addEventListener('click', () => show(current + 1));
previous.addEventListener('click', () => show(current - 1));
document.addEventListener('keydown', event => {
  if (event.altKey || event.ctrlKey || event.metaKey || event.target.closest('input,textarea,select,summary')) return;
  if (event.key === 'ArrowRight') { event.preventDefault(); show(current + 1); }
  if (event.key === 'ArrowLeft' && current > 0) { event.preventDefault(); show(current - 1); }
});
